INSERT INTO public.content_blocks VALUES ('checklist.B01', 'checklist', '{"key": "base", "lvl": "a", "ctaL": "Minha base está pronta", "intro": "São as contas que as duas trilhas usam. Faça uma por vez: cada item tem o passo a passo e a aula.", "items": [{"d": "Protege a conta principal: sem ela, quem descobrir sua senha entra.", "l": "E-mail com verificação em duas etapas", "aula": "1.6", "como": "email"}, {"d": "Instagram, Facebook e TikTok protegidos do mesmo jeito.", "l": "Redes com verificação em duas etapas", "aula": "2.2", "como": "redes"}, {"d": "Onde você pega seu link e recebe a comissão. [rede de afiliação a definir]", "l": "Conta na rede de afiliação", "aula": "2.3", "como": "rede"}, {"d": "A rede manda o dinheiro pra cá. Você saca quando quiser.", "l": "Conta Wise pra receber em dólar", "aula": "2.4", "como": "wise"}], "titulo": "Sua base"}', '2026-11-05 01:43:36.275498+00') ON CONFLICT DO NOTHING;
INSERT INTO public.content_blocks VALUES ('checklist.B03', 'checklist', '{"key": "anuncios", "lvl": "a", "ctaL": "Base de anúncios pronta", "intro": "Só pra trilha paga. É a parte da Meta onde ficam suas campanhas e o cartão que paga os anúncios.", "items": [{"d": "A \"empresa\" sua dentro da Meta.", "l": "Portfólio empresarial criado", "aula": "P1.2", "como": "portfolio"}, {"d": "Onde ficam as campanhas.", "l": "Conta de anúncios criada", "aula": "P1.2", "como": "contaads"}, {"d": "O limite protege você de gastar mais do que planejou.", "l": "Cartão cadastrado e limite definido", "aula": "P1.3", "como": "cartao"}], "titulo": "Base de anúncios"}', '2026-11-05 01:43:36.275498+00') ON CONFLICT DO NOTHING;
INSERT INTO public.content_blocks VALUES ('checklist.B04', 'checklist', '{"key": "contas", "lvl": "a", "ctaL": "Minhas contas estão protegidas", "intro": "Antes de crescer, proteja o que você construiu.", "items": [{"d": "E-mail, redes, Meta, rede de afiliação e Wise.", "l": "Duas etapas ativas em todas as contas", "aula": "7.7"}, {"d": "Se perder o celular, você recupera.", "l": "E-mail e telefone de recuperação atualizados"}, {"d": "Nem quem promete ajudar.", "l": "Ninguém mais tem sua senha"}, {"d": "Conta com pagamento atrasado pode ser travada.", "l": "Pagamentos da conta de anúncios em dia"}], "titulo": "Contas protegidas"}', '2026-11-05 01:43:36.275498+00') ON CONFLICT DO NOTHING;
INSERT INTO public.content_blocks VALUES ('checklist.PG04', 'checklist', '{"key": "meta", "lvl": "p", "aula": "P2.7", "ctaL": "Os 3 anúncios passaram", "intro": "Passe os 3 anúncios por aqui antes de subir. Anúncio fora da regra é reprovado ou trava a conta.", "items": [{"d": "Nem em foto, nem em frase.", "l": "Sem antes e depois"}, {"d": "Nada de \"resolve em 7 dias\".", "l": "Sem promessa de ganho, cura ou prazo"}, {"d": "Evite \"você está acima do peso?\" ou \"você é...\".", "l": "Não fala da pessoa"}, {"d": "Prometa só o que está no produto.", "l": "O texto bate com o que o produto entrega"}, {"d": "Confira antes de publicar.", "l": "O link é o do seu funil"}], "titulo": "Regras da Meta"}', '2026-11-05 01:43:36.275498+00') ON CONFLICT DO NOTHING;
INSERT INTO public.content_blocks VALUES ('checklist.PG05', 'checklist', '{"key": "pixel", "lvl": "p", "ctaL": "Meu pixel funciona", "field": {"d": "Fica no Gerenciador de Eventos da Meta. A aula P3.2 mostra onde.", "l": "ID do seu pixel", "ph": "Cole aqui o número do pixel"}, "intro": "O pixel é o \"olho\" da Meta na sua página: ele avisa quando alguém compra, e a Meta aprende pra quem mostrar o anúncio.", "items": [{"d": "No Gerenciador de Eventos.", "l": "Pixel criado na Meta", "aula": "P3.2", "como": "pixelcriar"}, {"d": "No campo de pixel da [ferramenta de página]. Funil direto: pule.", "l": "Pixel colado na sua página", "aula": "P3.3", "como": "pixelpagina"}, {"d": "Assim a venda na página do produtor também conta.", "l": "Pixel cadastrado na rede de afiliação", "aula": "P3.4", "como": "pixelrede"}, {"d": "Checklist \"meu pixel funciona?\".", "l": "Teste: abri a página e o evento apareceu", "aula": "P3.5"}], "titulo": "Seu pixel"}', '2026-11-05 01:43:36.275498+00') ON CONFLICT DO NOTHING;
INSERT INTO public.content_blocks VALUES ('checklist.PG07', 'checklist', '{"key": "subida", "lvl": "p", "aula": "P4.6", "ctaL": "Publiquei minha campanha", "intro": "Confira tudo antes de publicar. Depois de publicar, o app anota a data: nos primeiros dias a Meta está aprendendo e você não mexe.", "items": [{"l": "Campanha com objetivo Vendas"}, {"d": "Do seu plano de campanha.", "l": "Valor por dia e país preenchidos"}, {"l": "Público aberto"}, {"l": "Posicionamentos conferidos"}, {"l": "3 anúncios com o link do seu funil"}, {"l": "Os 3 passaram nas regras da Meta"}], "titulo": "Checklist de subida"}', '2026-11-05 01:43:36.275498+00') ON CONFLICT DO NOTHING;
INSERT INTO public.content_blocks VALUES ('checklist.OG03', 'checklist', '{"key": "aquec", "lvl": "p", "aula": "O1.6", "ctaL": "Aquecimento feito", "intro": "Perfil novo precisa agir como gente de verdade antes de postar todo dia. Uma tarefa por dia. (Tarefas de exemplo: o time define o roteiro final.)", "items": [{"l": "Dia 1 · Completar o perfil e assistir vídeos do seu assunto"}, {"l": "Dia 2 · Curtir e comentar em vídeos do nicho"}, {"l": "Dia 3 · Seguir perfis do nicho e salvar vídeos"}, {"l": "Dia 4 · Primeiro post"}, {"l": "Dia 5 · Responder comentários e interagir"}, {"l": "Dia 6 · Segundo post"}, {"l": "Dia 7 · Terceiro post e revisar a bio"}], "titulo": "Aquecimento do perfil"}', '2026-11-05 01:43:36.275498+00') ON CONFLICT DO NOTHING;
INSERT INTO public.content_blocks VALUES ('checklist.OG09', 'checklist', '{"key": "perfil", "lvl": "p", "aula": "O4.5", "ctaL": "Perfil revisado", "intro": "Passe os 3 últimos posts e o perfil por aqui. Se o alcance caiu, quase sempre é uma dessas coisas.", "items": [{"l": "Nenhum vídeo copiado ou repostado de outra pessoa"}, {"l": "Sem promessa de ganho, cura ou antes e depois"}, {"l": "A bio diz pra quem é e tem o link"}, {"l": "O link da bio abre e leva pro funil"}, {"l": "Postando na frequência do seu calendário"}, {"l": "Sem comprar seguidor nem usar robô"}], "titulo": "Revisão do perfil"}', '2026-11-05 01:43:36.275498+00') ON CONFLICT DO NOTHING;
INSERT INTO public.content_blocks VALUES ('checklist.E01', 'checklist', '{"key": "escalar", "lvl": "p", "aula": "7.1", "ctaL": "Tudo marcado, posso escalar", "intro": "Escalar é aumentar o que já dá lucro, com cuidado. Se algum item não estiver marcado, ainda não é hora: siga na rotina.", "items": [{"l": "Vendi mais de uma vez em [período, regra do time]"}, {"d": "Etapa Dinheiro.", "l": "A planilha de lucro da semana fechou no positivo"}, {"l": "Funil e pixel funcionando"}, {"d": "Checklist da aula 7.7.", "l": "Contas protegidas"}], "titulo": "Posso escalar?"}', '2026-11-05 01:43:36.275498+00') ON CONFLICT DO NOTHING;
INSERT INTO public.content_blocks VALUES ('checklist.DN03', 'checklist', '{"key": "saque", "lvl": "p", "aula": "6.3", "ctaL": "Dados de saque conferidos", "intro": "Antes do primeiro saque, confira se o dinheiro vai cair no lugar certo.", "items": [{"l": "A Wise está cadastrada na rede como conta de saque"}, {"l": "O nome na Wise é igual ao da rede"}, {"l": "A moeda do saque é a certa"}], "titulo": "Dados de saque"}', '2026-11-05 01:43:36.275498+00') ON CONFLICT DO NOTHING;
INSERT INTO public.content_blocks VALUES ('passos.publicar', 'passos', '["Publicar", ["Toque em Publicar.", "Copie o endereço da página.", "Volte pro app e cole em \"Conferir minha página\".", "O app confere tudo pra você."], "4.7"]', '2026-11-05 01:43:36.275498+00') ON CONFLICT DO NOTHING;
INSERT INTO public.content_blocks VALUES ('info.PG08', 'info', '{"ctaL": "Salvar a tabela", "cards": [["Em análise", "A Meta está revisando. Espere: não edite nem apague o anúncio."], ["Reprovado", "Leia o motivo. Ajuste o texto ou a imagem na tela de ajustar anúncio e peça nova revisão."], ["Aprendizado ou veiculação limitada", "Normal no começo. Não mexa até passar o período de aprendizado."], ["Conta de anúncios restrita", "Não crie outra conta. Fale com o time pelo suporte."], ["Pagamento recusado", "Confira o cartão e o limite em Cobrança e pagamentos."]], "intro": "Quando a Meta mostrar um aviso, procure aqui o que fazer.", "aulaId": "P4.7"}', '2026-11-05 01:43:36.275498+00') ON CONFLICT DO NOTHING;
INSERT INTO public.content_blocks VALUES ('checklist.F05pre', 'checklist', '{"key": "monte", "lvl": "p", "aula": "4.7", "ctaL": "Já montei, conferir minha página", "cta2L": "Abrir meu kit de novo", "intro": "Você não cria página de vendas: a do produtor já existe e já vende. Aqui você monta uma página curta sua, com o texto pronto do kit, num modelo que já vem arrumado. Um passo por vez.", "items": [{"d": "O time escolhe uma ferramenta simples, que funciona no celular.", "l": "Criar sua conta grátis na [ferramenta de página]", "como": "ferramenta"}, {"d": "Um toque no link do modelo e ele vira seu.", "l": "Duplicar o modelo de pré-venda do SDM", "como": "modelo"}, {"d": "Copie no kit e cole no lugar do título do modelo.", "l": "Trocar o título pelo bloco 1 do kit", "como": "colar"}, {"d": "Abertura, problema, virada, o que é e pra quem.", "l": "Colar os blocos 2 a 6, na ordem", "como": "colar"}, {"d": "Use o prompt do kit ou uma foto sua, sem rosto se preferir.", "l": "Colocar a imagem", "como": "imagem"}, {"d": "É isso que marca que a venda veio de você.", "l": "No botão, colar seu link de afiliada", "como": "botao"}, {"d": "Você cola esse endereço no próximo passo.", "l": "Publicar e copiar o endereço da página", "como": "publicar"}], "titulo": "Monte comigo"}', '2026-11-05 01:43:36.275498+00') ON CONFLICT DO NOTHING;
INSERT INTO public.content_blocks VALUES ('checklist.F05quiz', 'checklist', '{"key": "monte", "lvl": "p", "aula": "4.7", "ctaL": "Já montei, conferir meu quiz", "cta2L": "Abrir meu kit de novo", "intro": "Você não cria página de vendas: a do produtor já existe e já vende. Aqui você monta um quiz curto seu, com as perguntas prontas do kit, num modelo que já vem arrumado.", "items": [{"d": "O time escolhe uma ferramenta simples, que funciona no celular.", "l": "Criar sua conta grátis na [ferramenta de quiz]", "como": "ferramenta"}, {"d": "Um toque no link do modelo e ele vira seu.", "l": "Duplicar o modelo de quiz do SDM", "como": "modelo"}, {"d": "Na ordem do kit.", "l": "Colar as 3 perguntas e as respostas", "como": "colar"}, {"l": "Colar o texto do resultado", "como": "colar"}, {"d": "É isso que marca que a venda veio de você.", "l": "No botão do resultado, colar seu link de afiliada", "como": "botao"}, {"l": "Publicar e copiar o endereço do quiz", "como": "publicar"}], "titulo": "Monte comigo"}', '2026-11-05 01:43:36.275498+00') ON CONFLICT DO NOTHING;
INSERT INTO public.content_blocks VALUES ('checklist.F07', 'checklist', '{"key": "teste", "lvl": "p", "aula": "4.6", "ctaL": "Meu funil está no ar", "intro": "Agora você faz o caminho do cliente, do começo ao fim. Não precisa comprar: só ver que chega.", "items": [{"d": "Do jeito que o cliente vai ver.", "l": "Abri minha página no celular"}, {"d": "Tem que abrir na hora.", "l": "Toquei no botão"}, {"l": "Caí na página do produtor"}, {"l": "Cheguei no checkout do produtor", "aula": "4.6"}, {"d": "O código de afiliada aparece no endereço ou a rede confirma.", "l": "O link é o meu"}], "titulo": "Teste do caminho"}', '2026-11-05 01:43:36.275498+00') ON CONFLICT DO NOTHING;
INSERT INTO public.content_blocks VALUES ('checklist.F07dir', 'checklist', '{"key": "teste", "lvl": "p", "aula": "4.6", "ctaL": "Meu funil está no ar", "intro": "No funil direto, o anúncio ou o link da bio leva pro seu link de afiliada. Faça o caminho do cliente.", "items": [{"l": "Abri meu link de afiliada no celular"}, {"l": "Caí na página do produtor"}, {"l": "Cheguei no checkout do produtor", "aula": "4.6"}, {"l": "O código de afiliada é o meu"}], "titulo": "Teste do caminho"}', '2026-11-05 01:43:36.275498+00') ON CONFLICT DO NOTHING;
INSERT INTO public.content_blocks VALUES ('passos.email', 'passos', '["Verificação em duas etapas no e-mail", ["Abra as configurações de segurança da sua conta de e-mail.", "Toque em \"Verificação em duas etapas\".", "Escolha receber o código por SMS ou por um app de autenticação.", "Guarde os códigos reservas num lugar seguro."], "1.6"]', '2026-11-05 01:43:36.275498+00') ON CONFLICT DO NOTHING;
INSERT INTO public.content_blocks VALUES ('passos.redes', 'passos', '["Duas etapas nas redes", ["No Instagram, abra Configurações e procure \"Senha e segurança\".", "Ative a autenticação de dois fatores.", "Faça o mesmo no Facebook e no TikTok.", "Teste: saia e entre de novo usando o código."], "2.2"]', '2026-11-05 01:43:36.275498+00') ON CONFLICT DO NOTHING;
INSERT INTO public.content_blocks VALUES ('passos.rede', 'passos', '["Conta na rede de afiliação", ["Abra o site da [rede de afiliação] e toque em criar conta.", "Use seu nome verdadeiro e o e-mail com duas etapas.", "Confirme o e-mail.", "Complete o perfil de afiliada e os dados de pagamento (Wise)."], "2.3"]', '2026-11-05 01:43:36.275498+00') ON CONFLICT DO NOTHING;
INSERT INTO public.content_blocks VALUES ('passos.wise', 'passos', '["Conta Wise pra receber em dólar", ["Baixe o app Wise na loja do celular.", "Crie a conta com seu e-mail e escolha conta pessoal.", "Envie o documento e a selfie que o app pedir.", "Abra os dados da conta em dólar: é isso que você cadastra na rede."], "2.4"]', '2026-11-05 01:43:36.275498+00') ON CONFLICT DO NOTHING;
INSERT INTO public.content_blocks VALUES ('passos.portfolio', 'passos', '["Portfólio empresarial", ["Entre no Meta Business com o seu Facebook.", "Toque em criar portfólio empresarial.", "Use seu nome e o e-mail de trabalho.", "Confirme o e-mail."], "P1.2"]', '2026-11-05 01:43:36.275498+00') ON CONFLICT DO NOTHING;
INSERT INTO public.content_blocks VALUES ('passos.contaads', 'passos', '["Conta de anúncios", ["No portfólio, abra as configurações de contas de anúncios.", "Toque em adicionar e criar uma conta nova.", "Escolha o fuso horário e a moeda do país onde você mora.", "Dê acesso total a você mesma."], "P1.2"]', '2026-11-05 01:43:36.275498+00') ON CONFLICT DO NOTHING;
INSERT INTO public.content_blocks VALUES ('passos.cartao', 'passos', '["Cartão e limite", ["Na conta de anúncios, abra Cobrança e pagamentos.", "Adicione o cartão.", "Defina o limite de gastos da conta.", "Confira se a moeda está certa."], "P1.3"]', '2026-11-05 01:43:36.275498+00') ON CONFLICT DO NOTHING;
INSERT INTO public.content_blocks VALUES ('passos.pixelcriar', 'passos', '["Criar o pixel", ["Abra o Gerenciador de Eventos da Meta.", "Toque em conectar dados e escolha Web.", "Dê um nome ao pixel e crie.", "Copie o ID do pixel e cole no app."], "P3.2"]', '2026-11-05 01:43:36.275498+00') ON CONFLICT DO NOTHING;
INSERT INTO public.content_blocks VALUES ('passos.pixelpagina', 'passos', '["Pixel na sua página", ["Abra sua página na [ferramenta de página].", "Procure o campo de pixel ou de código da Meta.", "Cole o ID do seu pixel.", "Publique de novo."], "P3.3"]', '2026-11-05 01:43:36.275498+00') ON CONFLICT DO NOTHING;
INSERT INTO public.content_blocks VALUES ('passos.pixelrede', 'passos', '["Pixel na rede de afiliação", ["Na [rede de afiliação], abra o produto que você divulga.", "Procure \"pixel\" ou \"rastreamento\".", "Cole o ID do pixel e salve.", "Faça o teste \"meu pixel funciona?\"."], "P3.4"]', '2026-11-05 01:43:36.275498+00') ON CONFLICT DO NOTHING;
INSERT INTO public.content_blocks VALUES ('passos.ferramenta', 'passos', '["Conta na ferramenta", ["Toque no link da ferramenta que está no app.", "Crie a conta com seu e-mail.", "Escolha o plano grátis.", "Volte pro app e marque este passo."], "4.7"]', '2026-11-05 01:43:36.275498+00') ON CONFLICT DO NOTHING;
INSERT INTO public.content_blocks VALUES ('passos.modelo', 'passos', '["Duplicar o modelo do SDM", ["Toque em \"Abrir modelo do SDM\" no app.", "Na ferramenta, toque em duplicar ou usar modelo.", "O modelo vira uma página sua, já arrumada.", "Dê um nome simples, tipo o nome do produto."], "4.7"]', '2026-11-05 01:43:36.275498+00') ON CONFLICT DO NOTHING;
INSERT INTO public.content_blocks VALUES ('passos.colar', 'passos', '["Colar o texto do kit", ["No app, abra o kit e toque em Copiar no bloco.", "Na ferramenta, toque no texto do modelo e apague.", "Cole o texto do kit.", "Faça o mesmo com cada bloco, na ordem."], "4.4"]', '2026-11-05 01:43:36.275498+00') ON CONFLICT DO NOTHING;
INSERT INTO public.content_blocks VALUES ('passos.imagem', 'passos', '["Trocar a imagem", ["Copie o prompt de imagem do kit.", "Gere a imagem na IA de imagem que o time indicar, ou use uma foto sua.", "Na ferramenta, toque na imagem do modelo e troque.", "Confira se aparece bem no celular."], "4.7"]', '2026-11-05 01:43:36.275498+00') ON CONFLICT DO NOTHING;
INSERT INTO public.content_blocks VALUES ('passos.botao', 'passos', '["Link no botão", ["Toque no botão do modelo.", "Procure o campo \"link\" ou \"URL\".", "Cole o seu link de afiliada, o mesmo que você testou no app.", "Salve."], "4.6"]', '2026-11-05 01:43:36.275498+00') ON CONFLICT DO NOTHING;
INSERT INTO public.content_blocks VALUES ('info.DN02', 'info', '{"ctaL": "Entendi", "cards": [["Venda feita", "A rede registra sua comissão como pendente."], ["Prazo de garantia", "O cliente pode pedir reembolso nesse período. [prazo da sua rede]"], ["Comissão liberada", "Aparece como disponível na rede."], ["Saque pra Wise", "Você pede o saque na rede."], ["Na sua conta", "O dinheiro chega na Wise em dólar. [prazo da rede]"]], "intro": "A comissão não cai na hora. Esse é o caminho, do dia da venda até a sua conta.", "aulaId": "6.2"}', '2026-11-05 01:43:36.275498+00') ON CONFLICT DO NOTHING;
INSERT INTO public.content_blocks VALUES ('info.DN05', 'info', '{"ctaL": "Salvar as 5 perguntas", "nota": "Isso não é orientação fiscal. Quem responde é um contador do país onde você mora.", "cards": [["Preciso declarar o que recebo como afiliada no país onde moro?"], ["Como declaro dinheiro que vem de fora, em dólar?"], ["Preciso abrir empresa ou algum registro?"], ["Posso descontar o que gasto com anúncio?"], ["Quanto devo separar de cada saque pra imposto?"]], "intro": "Imposto depende do país onde você mora. Leve estas 5 perguntas pra um contador de lá.", "aulaId": "6.5"}', '2026-11-05 01:43:36.275498+00') ON CONFLICT DO NOTHING;
INSERT INTO public.content_blocks VALUES ('entenda.EN0', 'entenda', '{"cta": "Ver o país sugerido", "tag": "ENTENDA · ETAPA 0", "next": "V07", "aulas": ["3.4"], "texto": "País e idioma de venda são de quem compra, não seus. Como você mora fora, pode vender pra gente de lá e ganhar em dólar, libra ou euro.", "duvida": {"q": "E se eu não falo inglês?", "r": "A IA escreve tudo no idioma do cliente e mostra a tradução pra você entender."}, "passos": ["Ver o país que a IA sugeriu pelo seu diagnóstico", "Entender o motivo", "Confirmar ou trocar (dá pra mudar depois)"], "porque": "Cada país tem um idioma, uma moeda e mais ou menos gente vendendo a mesma coisa. Tudo que a IA gera depois sai nesse idioma.", "titulo": "Pra quem você vai vender?"}', '2026-11-05 01:43:36.275498+00') ON CONFLICT DO NOTHING;
INSERT INTO public.content_blocks VALUES ('entenda.EN1', 'entenda', '{"cta": "Ver o produto escolhido", "tag": "ENTENDA · ETAPA 1", "next": "V04", "aulas": ["3.1", "3.5", "3.6"], "texto": "Como afiliada, você divulga um produto que já existe. Quem criou (o produtor) entrega e atende. Você ganha uma comissão por cada venda feita pelo seu link.", "duvida": {"q": "Preciso comprar o produto?", "r": "Não. Você só precisa entender pra quem ele é e o que ele resolve."}, "passos": ["Ver o produto que a IA escolheu pra você", "Pegar seu link de afiliada na rede", "Preencher o cartão \"esse produto ajuda quem...\""], "porque": "Produto bom resolve uma dor clara de um tipo de pessoa, no seu idioma de venda, e rende conteúdo. A IA escolhe com base no seu diagnóstico e explica o porquê.", "titulo": "Você divulga o produto de outra pessoa"}', '2026-11-05 01:43:36.275498+00') ON CONFLICT DO NOTHING;
INSERT INTO public.content_blocks VALUES ('entenda.EN4', 'entenda', '{"cta": "Ver meus números", "tag": "ENTENDA · ETAPA 4", "next": "N00", "aulas": ["P5.1", "O5.1"], "texto": "Você não precisa entender tudo do gerenciador ou do painel da rede. Precisa olhar poucos números, sempre os mesmos, e saber o que cada um diz.", "duvida": {"q": "Gastei e não vendi. Errei?", "r": "Ainda não dá pra saber. O diagnóstico mostra em que parte as pessoas estão parando."}, "passos": ["Anotar os números da semana", "Fazer o diagnóstico guiado", "Ir direto na parte que precisa de ajuste"], "porque": "Cada número aponta uma parte do funil: o anúncio ou o vídeo, a sua página, a página do produtor. Assim você ajusta a parte certa em vez de mudar tudo.", "titulo": "Número tira o \"será que está dando certo?\""}', '2026-11-05 01:43:36.275498+00') ON CONFLICT DO NOTHING;
INSERT INTO public.content_blocks VALUES ('entenda.EN5', 'entenda', '{"cta": "Registrar minha venda", "tag": "ENTENDA · ETAPA 5", "next": "DN01", "aulas": ["6.1", "6.2"], "texto": "A comissão não cai na hora: ela passa por um prazo na rede de afiliação, depois você saca pra Wise.", "duvida": {"q": "Preciso pagar imposto?", "r": "Depende do país onde você mora. A gente te dá as 5 perguntas pra levar a um contador."}, "passos": ["Registrar sua 1ª venda", "Ver quando a comissão libera e conferir o saque", "Preencher a planilha de lucro"], "porque": "Entender o caminho evita susto e mostra quanto sobrou de verdade depois do que você gastou.", "titulo": "Da venda até o dinheiro na sua conta"}', '2026-11-05 01:43:36.275498+00') ON CONFLICT DO NOTHING;
INSERT INTO public.content_blocks VALUES ('entenda.EN6', 'entenda', '{"cta": "Passar o checklist", "tag": "ENTENDA · ETAPA 6", "next": "E01", "aulas": ["7.1"], "texto": "Escalar é aumentar o que já dá lucro: mais verba no que funciona, uma 2ª rede, um novo país ou um novo produto.", "duvida": {"q": "Quando sei que é hora?", "r": "Quando o checklist estiver todo marcado. Antes disso, continue na rotina."}, "passos": ["Passar o checklist \"posso escalar?\"", "Escolher o próximo degrau", "Proteger suas contas"], "porque": "Quem aumenta rápido demais costuma perder o que funcionava. Por isso cada degrau tem um checklist.", "titulo": "Crescer sem colocar tudo em risco"}', '2026-11-05 01:43:36.275498+00') ON CONFLICT DO NOTHING;
