 "N00"], "N02": ["Etapa 4 · P5.5", "Não vendeu?", "N00"], "N03": ["Etapa 4 · O5", "Números do orgânico", "N00"], "N04": ["Etapa 4 · O5.3 e O5.4", "O vídeo que não foi", "N00"], "Q02": ["Professora", "Falar com o time", "Q01"], "T01": ["Estratégia · aula 5.4", "Prós e contras", "I01"], "T02": ["Estratégia · aula 5.5", "Três mulheres, três caminhos", "T01"], "T03": ["Estratégia · aula 5.6", "Sua decisão", "T02"], "V02": ["Produtos", "Vitrine", "V01"], "V03": ["Vitrine · aula 3.1", "", "V02"], "V04": ["Etapa 1 · aula 3.5", "Por que esse produto", "V05"], "V05": ["Pasta do produto", "", "V01"], "V06": ["Pasta do produto", "Ficha do produto", "V05"], "V07": ["Etapa 0 · aula 3.4", "País e idioma de venda", "V05"], "V08": ["Etapa 1 · aula 3.6", "Seu link de afiliada", "V05"], "V09": ["Pasta do produto", "Biblioteca", "V05"], "DN01": ["Etapa 5 · aula 6.1", "Sua 1ª venda", "V05"], "DN02": ["Etapa 5 · aula 6.2", "Da venda ao saque", "V05"], "DN03": ["Etapa 5 · aula 6.3", "Dados de saque", "V05"], "DN04": ["Etapa 5 · aula 6.4", "Planilha de lucro", "V05"], "DN05": ["Etapa 5 · aula 6.5", "5 perguntas pro contador", "V05"], "DV01": ["Etapa 3", "Sua divulgação", "V05"], "FR01": ["Ferramenta · aula 1.4", "Calculadora de lucro por venda", "I05"], "FR02": ["Ferramenta · B1 e 5.2", "Verba do 1º mês", "I05"], "FR03": ["Ferramenta · aula P2.6", "Teste de anúncio", "I05"], "FR04": ["Ferramenta · P5.6 e O5.5", "Rotina dos 10 minutos", "I05"], "OG01": ["Trilha orgânica · O1.2 e O1.3", "Sua rede", "DV01"], "OG02": ["Trilha orgânica · O1.4 e O1.5", "Perfil temático", "DV01"], "OG03": ["Trilha orgânica · O1.6", "Aquecimento", "DV01"], "OG04": ["Trilha orgânica · O2", "Ganchos e virais", "DV01"], "OG05": ["Trilha orgânica · O3.1", "Roteiros com IA", "DV01"], "OG06": ["Trilha orgânica · O4.1", "Calendário", "DV01"], "OG07": ["Trilha orgânica · O3.4 e O4.2", "Legenda e chamada", "DV01"], "OG08": ["Trilha orgânica · O2.6", "Áudios e trends", "DV01"], "OG09": ["Trilha orgânica · O4.5 e O4.6", "Revisão do perfil", "DV01"], "PG01": ["Trilha paga · P2.1", "Seus 3 anúncios", "DV01"], "PG02": ["Trilha paga · P2.2 a P2.5", "Ajustar anúncio", "PG01"], "PG03": ["Trilha paga · P2.4", "Vídeo de 20 segundos", "PG01"], "PG04": ["Trilha paga · P2.7", "Regras da Meta", "DV01"], "PG05": ["Trilha paga · P3", "Pixel", "DV01"], "PG06": ["Trilha paga · P4.1 a P4.5", "Plano de campanha", "DV01"], "PG07": ["Trilha paga · P4.6", "Subir a campanha", "DV01"], "PG08": ["Trilha paga · P4.7", "Avisos da Meta", "DV01"]}', '2026-11-05 01:43:36.275498+00') ON CONFLICT DO NOTHING;
INSERT INTO public.content_blocks VALUES ('app.diagnostico', 'diagnostico', '[{"k": "pais", "o": ["Estados Unidos", "Portugal", "Reino Unido", "Irlanda", "Espanha", "Itália", "Outro"], "p": "é de lá que você conhece o jeito das pessoas e, muitas vezes, o idioma.", "q": "Em que país você mora?"}, {"k": "idiomas", "o": ["Português", "Inglês", "Espanhol", "Italiano", "Outro"], "p": "a IA escreve tudo no idioma do cliente, mas ajuda saber o que você entende.", "q": "Quais idiomas você fala, mesmo que pouco?", "multi": true}, {"k": "trabalho", "o": ["Limpeza", "Babá ou cuidadora", "Restaurante", "Outro trabalho", "Não estou trabalhando"], "p": "isso mostra seus horários livres e os assuntos que você conhece de perto.", "q": "Com o que você trabalha hoje?"}, {"k": "tempo", "o": ["30 minutos", "1 hora", "2 horas ou mais"], "p": "o caminho certo depende do tempo que você tem de verdade.", "q": "Quanto tempo por dia você consegue separar?"}, {"k": "verba", "o": ["Nada agora", "Um valor pequeno", "Um valor que não me aperta"], "p": "anúncio é pago por você. Se não der agora, tem o caminho orgânico.", "q": "Dá pra investir em anúncio agora?"}, {"k": "assuntos", "o": ["Cozinha e receitas", "Casa e organização", "Filhos e família", "Fé e devocional", "Inglês e idiomas", "Beleza e cuidado"], "p": "produto de um assunto que você gosta é mais fácil de divulgar.", "q": "Sobre o que você gosta de falar ou entende?", "multi": true}, {"k": "aparecer", "o": ["Sim, mostro o rosto", "Só voz e mãos", "Não quero aparecer"], "p": "não é obrigatório. Só muda o jeito de fazer conteúdo.", "q": "Você topa aparecer nos vídeos?"}, {"k": "exp", "o": ["Nunca", "Já tentei", "Já vendo"], "p": "pra IA saber de onde começar a explicar.", "q": "Já vendeu alguma coisa pela internet?"}]', '2026-11-05 01:43:36.275498+00') ON CONFLICT DO NOTHING;
INSERT INTO public.content_blocks VALUES ('app.paises', 'texto', '[{"k": "eua", "lang": "en", "nome": "Estados Unidos · inglês", "curto": "EUA · inglês", "moeda": "dólar", "idioma": "Inglês"}, {"k": "uk", "lang": "en", "nome": "Reino Unido · inglês", "curto": "Reino Unido · inglês", "moeda": "libra", "idioma": "Inglês"}, {"k": "latam", "lang": "es", "nome": "Latinos nos EUA · espanhol", "curto": "Latinos · espanhol", "moeda": "dólar", "idioma": "Espanhol"}, {"k": "esp", "lang": "es", "nome": "Espanha · espanhol", "curto": "Espanha · espanhol", "moeda": "euro", "idioma": "Espanhol"}]', '2026-11-05 01:43:36.275498+00') ON CONFLICT DO NOTHING;
INSERT INTO public.content_blocks VALUES ('app.lg', 'texto', '{"en": {"o": [["Almost every day", "Sometimes", "Rarely"], ["Searching online", "Apps and videos", "Nothing yet"], ["A simple step by step", "A ready-made plan", "Quick tips"]], "q": [null, null, null], "adC": "Tap the link to see how it works.", "leg": "Save this so you don''t lose it. The full guide is in the link in my bio.", "call": "The full guide is in the link in my bio.", "banco": [null, null, null, null, null, null, null], "botao": "See how it works", "virada": "There''s a simpler way to handle this, and it doesn''t take your whole weekend.", "chamadas": ["The full guide is in the link in my bio.", "Want the whole list? Link in bio.", "Follow for more, and the guide is in my bio."]}, "es": {"o": [["Casi todos los días", "A veces", "Casi nunca"], ["Buscar en internet", "Apps y videos", "Nada todavía"], ["Un paso a paso simple", "Un plan listo", "Consejos rápidos"]], "q": [null, null, null], "adC": "Toca el enlace para ver cómo funciona.", "leg": "Guárdalo para no perderlo. La guía completa está en el enlace de mi perfil.", "call": "La guía completa está en el enlace de mi perfil.", "banco": [null, null, null, null, null, null, null], "botao": "Ver cómo funciona", "virada": "Hay una forma más simple de resolverlo, y no te lleva todo el fin de semana.", "chamadas": ["La guía completa está en el enlace de mi perfil.", "¿Quieres la lista completa? Enlace en el perfil.", "Sígueme para más, y la guía está en mi perfil."]}}', '2026-11-05 01:43:36.275498+00') ON CONFLICT DO NOTHING;
INSERT INTO public.glossary VALUES ('464623d6-d311-4b97-84b6-cde4b108a11a', 'Afiliada', 'Quem divulga o produto de outra pessoa e ganha parte de cada venda', true, '1.3', '2026-11-05 01:43:36.275498+00', '2026-11-05 01:43:36.275498+00') ON CONFLICT DO NOTHING;
INSERT INTO public.glossary VALUES ('cd82c081-e9c0-4d1d-ae44-50d92a9eb87d', 'Alcance', 'Quantas pessoas diferentes viram o vídeo ou o anúncio', true, NULL, '2026-11-05 01:43:36.275498+00', '2026-11-05 01:43:36.275498+00') ON CONFLICT DO NOTHING;
INSERT INTO public.glossary VALUES ('06cb4c15-4636-43a5-9bf8-1ac120e19d0e', 'Anúncio (criativo)', 'A imagem ou vídeo, com texto, que aparece no feed como propaganda', true, NULL, '2026-11-05 01:43:36.275498+00', '2026-11-05 01:43:36.275498+00') ON CONFLICT DO NOTHING;
INSERT INTO public.glossary VALUES ('84311297-99f6-45de-aa1b-3c1134632865', 'Aprendizado', 'Os primeiros dias em que a Meta descobre pra quem mostrar o anúncio', true, NULL, '2026-11-05 01:43:36.275498+00', '2026-11-05 01:43:36.275498+00') ON CONFLICT DO NOTHING;
INSERT INTO public.glossary VALUES ('cb23f979-f736-48fd-938d-9e5704fa5a10', 'Áudio em alta', 'Música ou som que muita gente está usando na semana', true, NULL, '2026-11-05 01:43:36.275498+00', '2026-11-05 01:43:36.275498+00') ON CONFLICT DO NOTHING;
INSERT INTO public.glossary VALUES ('7d5c1b46-f5b1-4ab1-a01a-1e316ac18b4f', 'Campanha', 'O andar de cima: onde se escolhe o objetivo (vendas)', true, 'P4.1', '2026-11-05 01:43:36.275498+00', '2026-11-05 01:43:36.275498+00') ON CONFLICT DO NOTHING;
INSERT INTO public.glossary VALUES ('0af5f36d-6971-46e0-be41-aa0302fd5ea1', 'Checkout', 'A página onde a pessoa paga', true, '4.6', '2026-11-05 01:43:36.275498+00', '2026-11-05 01:43:36.275498+00') ON CONFLICT DO NOTHING;
INSERT INTO public.glossary VALUES ('6255c3a5-0512-40df-94fa-831953e27941', 'Comissão', 'A parte do preço que fica com ela em cada venda', true, '1.4', '2026-11-05 01:43:36.275498+00', '2026-11-05 01:43:36.275498+00') ON CONFLICT DO NOTHING;
INSERT INTO public.glossary VALUES ('79c6b49b-2949-404f-8c86-6d213cc6bd64', 'Conjunto de anúncios', 'O andar do meio: verba, país e onde aparece', true, NULL, '2026-11-05 01:43:36.275498+00', '2026-11-05 01:43:36.275498+00') ON CONFLICT DO NOTHING;
INSERT INTO public.glossary VALUES ('25963599-49f8-4ab9-bffc-a1223143900a', 'Conta de anúncios', 'Onde ficam as campanhas e o cartão que paga', true, NULL, '2026-11-05 01:43:36.275498+00', '2026-11-05 01:43:36.275498+00') ON CONFLICT DO NOTHING;
INSERT INTO public.glossary VALUES ('7c368b8e-f3a7-45d9-bfe7-9e333f3f3b11', 'CPC', 'Quanto custou cada clique', true, 'P5.1', '2026-11-05 01:43:36.275498+00', '2026-11-05 01:43:36.275498+00') ON CONFLICT DO NOTHING;
INSERT INTO public.glossary VALUES ('d7a4094d-9cf7-4387-aade-710929a0cd66', 'CPM', 'Quanto custa mostrar o anúncio pra mil pessoas', true, 'P5.1', '2026-11-05 01:43:36.275498+00', '2026-11-05 01:43:36.275498+00') ON CONFLICT DO NOTHING;
INSERT INTO public.glossary VALUES ('91c12fa4-8453-487d-8107-c47402d674f5', 'CTR', 'De cada 100 que viram, quantos clicaram', true, 'P5.1', '2026-11-05 01:43:36.275498+00', '2026-11-05 01:43:36.275498+00') ON CONFLICT DO NOTHING;
INSERT INTO public.glossary VALUES ('d78f4369-edf5-4b06-9203-a2279e019e1c', 'Custo por venda', 'Quanto ela gastou em anúncio pra fazer uma venda', true, 'P5.1', '2026-11-05 01:43:36.275498+00', '2026-11-05 01:43:36.275498+00') ON CONFLICT DO NOTHING;
INSERT INTO public.glossary VALUES ('eaef2838-1194-4df2-bcc3-72bca3abdf0d', 'Escalar', 'Aumentar o que já dá lucro, com cuidado', true, '7.1', '2026-11-05 01:43:36.275498+00', '2026-11-05 01:43:36.275498+00') ON CONFLICT DO NOTHING;
INSERT INTO public.glossary VALUES ('82998ee5-b458-4d14-84ff-9e626793c37c', 'Funil', 'O caminho do anúncio ou vídeo até a compra', true, '4.1', '2026-11-05 01:43:36.275498+00', '2026-11-05 01:43:36.275498+00') ON CONFLICT DO NOTHING;
INSERT INTO public.glossary VALUES ('50ed85e8-7a69-46be-bc09-884be226e99a', 'Gancho', 'A primeira frase ou imagem, que faz parar de rolar', true, 'P2.2', '2026-11-05 01:43:36.275498+00', '2026-11-05 01:43:36.275498+00') ON CONFLICT DO NOTHING;
INSERT INTO public.glossary VALUES ('a67e3d0f-2261-42e2-b423-5c13d561158b', 'Infoproduto', 'Conhecimento empacotado: e-book, curso, app, guia', true, NULL, '2026-11-05 01:43:36.275498+00', '2026-11-05 01:43:36.275498+00') ON CONFLICT DO NOTHING;
INSERT INTO public.glossary VALUES ('3b3003cf-be44-4309-8606-c0ed1b20195f', 'Link da bio', 'O link que fica no perfil e leva pro funil', true, NULL, '2026-11-05 01:43:36.275498+00', '2026-11-05 01:43:36.275498+00') ON CONFLICT DO NOTHING;
INSERT INTO public.glossary VALUES ('6bacbac8-b318-45dd-b0c7-46daa448daf7', 'Link de afiliada', 'O link que marca que a venda veio dela', true, '3.6', '2026-11-05 01:43:36.275498+00', '2026-11-05 01:43:36.275498+00') ON CONFLICT DO NOTHING;
INSERT INTO public.glossary VALUES ('801760e0-59b2-4023-a0ef-c63e2c6180a5', 'Meta', 'A empresa dona do Facebook e do Instagram', true, NULL, '2026-11-05 01:43:36.275498+00', '2026-11-05 01:43:36.275498+00') ON CONFLICT DO NOTHING;
INSERT INTO public.glossary VALUES ('2027f107-808f-4f51-9f05-884ecd8712b8', 'Orgânico', 'Vídeo ou post que alcança gente sem pagar anúncio', true, '1.5', '2026-11-05 01:43:36.275498+00', '2026-11-05 01:43:36.275498+00') ON CONFLICT DO NOTHING;
INSERT INTO public.glossary VALUES ('53299f78-5034-4409-ad60-d1fb486d7c4c', 'Perfil temático', 'Perfil sobre um assunto (receitas, inglês...), que não precisa mostrar o rosto', true, NULL, '2026-11-05 01:43:36.275498+00', '2026-11-05 01:43:36.275498+00') ON CONFLICT DO NOTHING;
