INSERT INTO public.glossary VALUES ('4d4a73e4-ebd1-4465-bb36-4d1ceb83eff2', 'Rede de afiliação', 'Plataforma que junta produtor e afiliada e paga a comissão', true, NULL, '2026-11-05 01:43:36.275498+00', '2026-11-05 01:43:36.275498+00') ON CONFLICT DO NOTHING;
