INSERT INTO public.glossary VALUES ('bad54172-d940-4979-8c90-ebfea20c48f2', 'Viralizar', 'Quando a rede mostra o vídeo pra muito mais gente do que segue o perfil', true, NULL, '2026-11-05 01:43:36.275498+00', '2026-11-05 01:43:36.275498+00') ON CONFLICT DO NOTHING;
