INSERT INTO public.modules VALUES ('M0', 'Boas-vindas', 'Tronco comum', 'Ela chegar, se sentir em casa, se ver na Amanda e entender o propósito por trás de tudo.', 'compra', '[{"titulo": "Mapa do caminho"}, {"titulo": "O combinado (1 página)"}, {"titulo": "Cartão \"minha palavra da jornada\""}, {"titulo": "Regras do grupo"}]', 0, '2026-11-05 01:43:36.275498+00', '2026-11-05 01:43:36.275498+00') ON CONFLICT DO NOTHING;
