INSERT INTO public.vitrine_products VALUES ('5899d967-7aad-4be2-80ed-d0da67729ea8', 'VIT-0021', 'Bedtime Prayers for Little Ones', NULL, NULL, 'en', '{EUA}', 'Fé e devocional', 'Ebook ilustrado', 'Orações curtas e ilustradas pra ler com os filhos antes de dormir.', 'mães cristãs que querem uma hora de dormir mais calma com os filhos', 'a hora de dormir virar briga em vez de um momento de calma', 'um ebook ilustrado com orações curtas pra ler com os filhos antes de dormir', 'Uma hora de dormir em paz, com orações curtas pras crianças', '["Bedtime used to be chaos at our house.", "The short prayer we say every night before the lights go off", "What we started doing at bedtime"]', 'Phone photo, mom and small child sitting on a bed with a children''s book, soft lamp light, cozy bedroom, realistic, faces not visible', '{#bedtimeroutine,#prayerforkids,#christianmom,#faithfamily}', true, false, 'baixa', 'direto', NULL, NULL, NULL, '{}', true, true, 2, '2026-11-05 01:43:36.275498+00', '2026-11-05 01:43:36.275498+00', '{"aX": "bedtime with kids", "aPt": "a hora de dormir das crianças", "dor": {"x": "bedtime turning into a fight instead of a calm moment", "pt": "a hora de dormir virar briga em vez de um momento de calma"}, "lang": "en", "oque": {"x": "an illustrated ebook of short bedtime prayers to read with your kids", "pt": "um ebook ilustrado com orações curtas pra ler com os filhos antes de dormir"}, "prom": {"x": "A peaceful bedtime with short prayers for kids", "pt": "Uma hora de dormir em paz, com orações curtas pras crianças"}, "quem": {"x": "Christian moms who want a calmer bedtime with their kids", "pt": "mães cristãs que querem uma hora de dormir mais calma com os filhos"}, "hooks": {"x": ["Bedtime used to be chaos at our house.", "The short prayer we say every night before the lights go off", "What we started doing at bedtime"], "pt": ["A hora de dormir era um caos aqui em casa.", "A oração curtinha que a gente faz toda noite antes de apagar a luz", "O que a gent